<?php declare(strict_types=1);$base=config('app.base_path');$trash=!empty($trash);?><div class="page-header"><div><h1><?= $trash?'Deleted Guides':'Local Guides' ?></h1><p>Manage local guides, languages, specialties, verification and daily rates.</p></div><div class="page-actions"><?php if($trash):?><a class="btn btn-secondary" href="<?= $base ?>/tourism/guides">Active Guides</a><?php else:?><a class="btn btn-secondary" href="<?= $base ?>/tourism/guides?view=trash">Trash</a><a class="btn btn-primary" href="<?= $base ?>/tourism/guides/create">Add Guide</a><?php endif;?></div></div><div class="card table-responsive"><table class="table"><thead><tr><th>Guide</th><th>Location</th><th>Languages</th><th>Specializations</th><th>Rate</th><th>Verification</th><th>Actions</th></tr></thead><tbody><?php if(empty($guides)):?><tr><td colspan="7"><div class="empty-state">No guides found.</div></td></tr><?php else:foreach($guides as $g):?><tr><td><strong><?= htmlspecialchars($g['name'],ENT_QUOTES,'UTF-8')?></strong><br><small><?= htmlspecialchars((string)($g['phone']??''),ENT_QUOTES,'UTF-8')?></small></td><td><?= htmlspecialchars((string)($g['city']??''),ENT_QUOTES,'UTF-8')?><br><small><?= htmlspecialchars((string)($g['district']??''),ENT_QUOTES,'UTF-8')?></small></td><td><?= htmlspecialchars((string)($g['languages']??''),ENT_QUOTES,'UTF-8')?></td><td><?= htmlspecialchars((string)($g['specializations']??''),ENT_QUOTES,'UTF-8')?></td><td><?= $g['price_per_day']!==null?'₹'.number_format((float)$g['price_per_day'],2).'/day':'—'?></td><td><?= htmlspecialchars($g['verification_status'],ENT_QUOTES,'UTF-8')?></td><td><?php if($trash):?><form method="post" action="<?= $base ?>/tourism/guides/<?= (int)$g['id']?>/restore"><button class="btn btn-secondary">Restore</button></form><?php else:?><a class="link-button" href="<?= $base ?>/tourism/guides/<?= (int)$g['id']?>">View</a> <a class="link-button" href="<?= $base ?>/tourism/guides/<?= (int)$g['id']?>/edit">Edit</a><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div>